  /* ─── FETCH LIVE DATA FROM FIRESTORE ─── */
  const fetchLiveData = useCallback(async () => {
    try {
      // Fetch project overrides
      const projSnap = await getDocs(collection(db, "projectData"));
      const projMap = {};
      projSnap.forEach(d => { projMap[d.id] = plainify(d.data()); });
      setLiveProjects(projMap);

      // Fetch community ROI overrides
      const roiSnap = await getDocs(collection(db, "communityROI"));
      const roiMap = {};
      roiSnap.forEach(d => { roiMap[d.id] = plainify(d.data()); });
      setLiveCommunityROI(roiMap);

      // Fetch community intel overrides
      try {
        const intelSnap = await getDocs(collection(db, "communityIntel"));
        const intelMap = {};
        intelSnap.forEach(d => { intelMap[d.id] = plainify(d.data()); });
        setLiveCommunityIntel(intelMap);
      } catch(e) {}

      // Fetch yield overrides
      const yieldSnap = await getDocs(collection(db, "yieldData"));
      const yieldMap = {};
      yieldSnap.forEach(d => { yieldMap[d.id] = plainify(d.data()); });
      setLiveYields(yieldMap);

      // Fetch price history (keyed by projectId)
      try {
        const histSnap = await getDocs(collection(db, "priceHistory"));
        const histMap = {};
        histSnap.forEach(d => {
          const data = plainify(d.data());
          const pid = data.projectId || data.pid;
          if (pid) {
            if (!histMap[pid]) histMap[pid] = [];
            histMap[pid].push({ id: d.id, ...data });
          }
        });
        // Sort each project's history by date
        Object.keys(histMap).forEach(pid => {
          histMap[pid].sort((a, b) => new Date(b.changedAt || b.recordedAt || 0) - new Date(a.changedAt || a.recordedAt || 0));
        });
        setPriceHistory(histMap);
      } catch(e) { console.error("Fetch price history:", e); }
    } catch (e) { console.error("Fetch live data:", e); }
  }, []);

  useEffect(() => { if (isAdmin) fetchLiveData(); }, [isAdmin, fetchLiveData]);

  // Real-time listeners for project and community data
